:root { font-family: system-ui, sans-serif; }
* { box-sizing: border-box; }
body { min-height: 100vh; margin: 0; padding: 40px 16px; color: #1d1d1f; background: #f5f5f7; }
.todo { max-width: 620px; margin: 0 auto; padding: clamp(24px, 6vw, 38px); border-radius: 20px; background: #ffffff; box-shadow: 0 12px 40px rgba(15,23,42,.08); }
.todo h1 { margin: 0 0 24px; }
#add-form label { display: block; margin-bottom: 8px; font-weight: 700; }
#add-form > div { display: flex; gap: 8px; }
input, button { min-height: 44px; border-radius: 9px; font: inherit; }
input { flex: 1; min-width: 0; padding: 11px 13px; border: 1px solid #cbd5e1; }
button { padding: 10px 16px; border: 1px solid #cbd5e1; color: #334155; background: #ffffff; cursor: pointer; }
#add-form button { border-color: #0369a1; color: #ffffff; background: #0369a1; font-weight: 700; }
.filters { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 18px; }
.filters button[aria-pressed="true"] { border-color: #0369a1; color: #ffffff; background: #0369a1; }
button:focus-visible, input:focus-visible { outline: 3px solid #38bdf8; outline-offset: 2px; }
#todo-status { min-height: 24px; color: #475569; }
#todo-list { margin: 0; padding: 0; list-style: none; }
#todo-list li { display: grid; grid-template-columns: auto 1fr auto auto; align-items: center; gap: 10px; padding: 13px 0; border-bottom: 1px solid #e2e8f0; }
#todo-list li.completed .task-text { color: #64748b; text-decoration: line-through; }
.task-text { overflow-wrap: anywhere; }
.danger { color: #b91c1c; }
@media (max-width: 480px) { #add-form > div { align-items: stretch; flex-direction: column; } #todo-list li { grid-template-columns: auto 1fr auto; } #todo-list .danger { grid-column: 2 / 4; } }

const storageKey = 'todos-v2';
const list = document.querySelector('#todo-list');
const form = document.querySelector('#add-form');
const input = document.querySelector('#new-todo');
const status = document.querySelector('#todo-status');
let filter = 'all';
let todos = loadTodos();

function loadTodos() {
  try {
    const value = JSON.parse(localStorage.getItem(storageKey) || '[]');
    return Array.isArray(value) ? value.filter(item => item && typeof item.text === 'string') : [];
  } catch {
    return [];
  }
}

function saveTodos() {
  localStorage.setItem(storageKey, JSON.stringify(todos));
}

function actionButton(label, action, id, className) {
  const button = document.createElement('button');
  button.type = 'button';
  button.textContent = label;
  button.dataset.action = action;
  button.dataset.id = id;
  if (className) button.className = className;
  return button;
}

function render() {
  list.replaceChildren();
  const visible = todos.filter(item => filter === 'all' || (filter === 'active' && !item.done) || (filter === 'done' && item.done));
  visible.forEach(item => {
    const row = document.createElement('li');
    row.classList.toggle('completed', item.done);
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = item.done;
    checkbox.dataset.action = 'toggle';
    checkbox.dataset.id = item.id;
    checkbox.setAttribute('aria-label', '标记任务“' + item.text + '”为完成');
    const text = document.createElement('span');
    text.className = 'task-text';
    text.textContent = item.text;
    row.append(checkbox, text, actionButton('编辑', 'edit', item.id), actionButton('删除', 'delete', item.id, 'danger'));
    list.append(row);
  });
  status.textContent = visible.length ? '当前显示 ' + visible.length + ' 个任务' : '当前筛选条件下没有任务';
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) return;
  todos.unshift({ id: crypto.randomUUID(), text, done: false });
  input.value = '';
  saveTodos();
  render();
});

list.addEventListener('click', event => {
  const control = event.target.closest('[data-action]');
  if (!control) return;
  const item = todos.find(todo => todo.id === control.dataset.id);
  if (!item) return;
  if (control.dataset.action === 'toggle') item.done = control.checked;
  if (control.dataset.action === 'edit') {
    const next = window.prompt('编辑任务', item.text);
    if (next !== null && next.trim()) item.text = next.trim().slice(0, 120);
  }
  if (control.dataset.action === 'delete') todos = todos.filter(todo => todo.id !== item.id);
  saveTodos();
  render();
});

document.querySelector('.filters').addEventListener('click', event => {
  const button = event.target.closest('button[data-filter]');
  if (!button) return;
  filter = button.dataset.filter;
  document.querySelectorAll('.filters button').forEach(item => item.setAttribute('aria-pressed', String(item === button)));
  render();
});
render();
